  /// The plural table, exposed read-only for the localization guard tests.
  static Map<String, Map<String, Map<String, String>>> get pluralTable => _pluralValues;

  /// CLDR plural category of [count] for [languageCode].
  ///
  /// Arabic: zero (0), one (1), two (2), few (n % 100 in 3–10),
  /// many (n % 100 in 11–99), other (100, 101, 102, … and fractions).
  /// English and Urdu: one (exactly 1), other.
  static String pluralCategory(String languageCode, num count) {
    if (count != count.truncate()) return 'other';
    final n = count.abs().toInt();
    if (languageCode == 'ar') {
      if (n == 0) return 'zero';
      if (n == 1) return 'one';
      if (n == 2) return 'two';
      final mod100 = n % 100;
      if (mod100 >= 3 && mod100 <= 10) return 'few';
      if (mod100 >= 11) return 'many';
      return 'other';
    }
    return n == 1 ? 'one' : 'other';
  }

  /// Looks up the plural form of [key] for [count] and substitutes {count}
  /// and each entry of [args], e.g. `plural('items_count', 3)` → "3 بنود".
  String plural(String key, num count, [Map<String, Object?> args = const {}]) {
    final lang = locale.languageCode;
    final table = _pluralValues[key];
    if (table == null) return key;
    final forms = table[lang] ?? table['en']!;
    final category = pluralCategory(lang, count);
    var value = (count == 0 ? forms['zero'] : null) ?? forms[category] ?? forms['other'] ?? key;
    final values = <String, Object?>{'count': count, ...args};
    values.forEach((name, arg) {
      value = value.replaceAll('{$name}', '${arg ?? ''}');
    });
    return value;
  }

  // ── General String Lookup ──────────────────────────────────────────────────
  String get(String key) {
    final lang = locale.languageCode;
    return _localizedValues[lang]?[key] ??
        _localizedValues['en']?[key] ??
        key;
  }

  /// Formats a Saudi Riyal amount for the active locale.
  ///
  /// English puts the currency code first ("SAR 1,250.00"); Arabic and Urdu
  /// put the localized unit after the number ("1,250.00 ر.س" / "1,250.00 ریال"),
  /// which reads naturally inside right-to-left text. Digits stay Western
  /// (the convention used by Saudi banking apps and receipts).
  String sar(num amount, {int decimals = 2}) {
    final pattern = decimals <= 0 ? '#,##0' : '#,##0.${'0' * decimals}';
    final number = NumberFormat(pattern, 'en_US').format(amount);
    final unit = get('sar');
    return locale.languageCode == 'en' ? '$unit $number' : '$number $unit';
  }

  /// Formats an amount in any account currency: SAR (or a blank code) goes
  /// through [sar]; another currency keeps its ISO code, before the number in
  /// English and after it in Arabic and Urdu. [signed] adds "+" to positive
  /// amounts (negative ones always carry "-").
  String money(num amount, String? currency, {int decimals = 2, bool signed = false}) {
    final code = (currency ?? '').trim().toUpperCase();
    final plus = signed && amount > 0 ? '+' : '';
    if (code.isEmpty || code == 'SAR') return '$plus${sar(amount, decimals: decimals)}';
    final pattern = decimals <= 0 ? '#,##0' : '#,##0.${'0' * decimals}';
    final number = NumberFormat(pattern, 'en_US').format(amount);
    return locale.languageCode == 'en' ? '$plus$code $number' : '$plus$number $code';
  }

  /// Formats [date] with an intl [pattern] in the active locale (month and
  /// weekday names localized, ASCII digits kept for consistency with amounts).
  /// Falls back to English when the locale's date symbols are not initialized
  /// (flutter_localizations initializes them for ar/ur in the running app).
  String date(DateTime date, String pattern) {
    try {
      final formatter = DateFormat(pattern, locale.languageCode)..useNativeDigits = false;
      return formatter.format(date);
    } catch (_) {
      return DateFormat(pattern, 'en_US').format(date);
    }
  }

  /// Localized "MMMM yyyy" label for a salary-cycle key such as "2026-11".
  /// Returns [fallback] when the key is not in that format.
  String cycleMonth(String cycleKey, {String fallback = ''}) {
    final m = RegExp(r'^(\d{4})-(\d{2})').firstMatch(cycleKey);
    if (m == null) return fallback.isNotEmpty ? fallback : cycleKey;
    return date(DateTime(int.parse(m.group(1)!), int.parse(m.group(2)!)), 'MMMM yyyy');
  }

  /// A salary cycle shown by its dates, e.g. "27 Oct – 26 Nov" (Arabic and
  /// Urdu month names, Western digits). Years are added only when the cycle
  /// is not entirely in the current (Riyadh) year, e.g. "27 Dec 2026 – 26 Jan 2027".
  String cycleRange(DateTime start, DateTime end, {DateTime? now}) {
    final year = SalaryCycleService.riyadhToday(now: now).year;
    final withYear = start.year != year || end.year != year;
    final pattern = withYear ? 'd MMM y' : 'd MMM';
    return '${date(start, pattern)} – ${date(end, pattern)}';
  }

  /// [cycleRange] for server ISO dates (`cycle_start` / `cycle_end`).
  String cycleRangeIso(String startIso, String endIso, {String fallback = '', DateTime? now}) {
    final start = DateTime.tryParse(startIso);
    final end = DateTime.tryParse(endIso);
    if (start == null || end == null) return fallback;
    return cycleRange(start, end, now: now);
  }

  /// [cycleRange] for a `YYYY-MM` cycle key and the household payday.
  /// Returns [fallback] (or the key) when the key is not in that format.
  String cycleLabel(String cycleKey, {int? paydayDay, String fallback = '', DateTime? now}) {
    final cycle = SalaryCycleService.cycleForKey(cycleKey, paydayDay: paydayDay);
    if (cycle == null) return fallback.isNotEmpty ? fallback : cycleKey;
    return cycleRange(cycle.start, cycle.end, now: now);
  }

  /// Looks up [key] and substitutes each `{name}` placeholder with the
  /// matching entry of [args], e.g. `format('across_accounts', {'count': 3})`.
  String format(String key, Map<String, Object?> args) {
    var value = get(key);
    args.forEach((name, arg) {
      value = value.replaceAll('{$name}', '${arg ?? ''}');
    });
    return value;
  }

  // ── Main Category Resolution ───────────────────────────────────────────────
  String category(String codeOrName) {
    final lang = locale.languageCode;
    final trimmed = codeOrName.trim();

    // 1. Exact match on code (e.g. OPEX-GROCERY)
    if (_categoryCodes.containsKey(trimmed)) {
      final map = _categoryCodes[trimmed]!;
      return map[lang] ?? map['en'] ?? trimmed;
    }

    // 2. Lookup by English or Arabic name
    for (final entry in _categoryCodes.values) {
      if (entry['en']?.toLowerCase() == trimmed.toLowerCase() ||
          entry['ar'] == trimmed ||
          entry['ur'] == trimmed) {
        return entry[lang] ?? entry['en'] ?? trimmed;
      }
    }

    // 3. Fallback: strip prefix if code-like
    if (trimmed.startsWith('OPEX-') || trimmed.startsWith('CAPEX-')) {
      final simple = trimmed.replaceFirst(RegExp(r'^[A-Z]+-'), '');
      return simple;
    }

    return trimmed;
  }

  // ── Sub-Category Resolution (Strict Single Language) ───────────────────────
  String subCategory(String subCodeOrName, {String? nameAr, String? nameEn}) {
    final lang = locale.languageCode;
    final cleanCode = subCodeOrName.trim();

    // 1. If explicit Arabic name provided from database and active language is Arabic:
    if (lang == 'ar') {
      if (nameAr != null && nameAr.trim().isNotEmpty) {
        return nameAr.trim();
      }
      final map = _subCategoryValues[cleanCode];
      if (map != null && map['ar'] != null) {
        return map['ar']!;
      }
      // Check if subCodeOrName is an English key in the dictionary
      for (final entry in _subCategoryValues.values) {
        if (entry['en']?.toLowerCase() == cleanCode.toLowerCase()) {
          return entry['ar'] ?? entry['en']!;
        }
      }
      return nameEn?.trim().isNotEmpty == true ? nameEn!.trim() : cleanCode;
    }

    // 2. If active language is Urdu:
    if (lang == 'ur') {
      final map = _subCategoryValues[cleanCode];
      if (map != null && map['ur'] != null) {
        return map['ur']!;
      }
      for (final entry in _subCategoryValues.values) {
        if (entry['en']?.toLowerCase() == cleanCode.toLowerCase()) {
          return entry['ur'] ?? entry['ar'] ?? entry['en']!;
        }
      }
      if (nameAr != null && nameAr.trim().isNotEmpty) {
        return nameAr.trim();
      }
      return nameEn?.trim().isNotEmpty == true ? nameEn!.trim() : cleanCode;
    }

    // 3. Default: English
    if (nameEn != null && nameEn.trim().isNotEmpty) {
      return nameEn.trim();
    }
    final map = _subCategoryValues[cleanCode];
    if (map != null && map['en'] != null) {
      return map['en']!;
    }
    for (final entry in _subCategoryValues.values) {
      if (entry['ar'] == cleanCode || entry['ur'] == cleanCode) {
        return entry['en'] ?? cleanCode;
      }
    }
    return cleanCode;
  }

  // ── Merchant Name Translation / Normalization ──────────────────────────────
  static const Map<String, Map<String, String>> _merchantDictionary = {
    'unknown': {
      'en': 'Unknown Merchant',
      'ar': 'تاجر غير محدد',
      'ur': 'نامعلوم تاجر',
    },
    'direct': {
      'en': 'Direct Entry',
      'ar': 'إدخال مباشر',
      'ur': 'براہ راست اندراج',
    },
    'manual': {
      'en': 'Manual Expense',
      'ar': 'مصروف يدوي',
      'ur': 'دستی خرچ',
    },
    'installment purchase': {
      'en': 'Installment Purchase',
      'ar': 'شراء بالتقسيط',
      'ur': 'قسط پر خریداری',
    },
    'panda': {
      'en': 'Panda Supermarket',
      'ar': 'أسواق بندة',
      'ur': 'پانڈا سپر مارکیٹ',
    },
    'othaim': {
      'en': 'Al Othaim Markets',
      'ar': 'أسواق العثيم',
      'ur': 'العثیم مارکیٹس',
    },
    'danube': {
      'en': 'Danube Supermarket',
      'ar': 'أسواق الدانوب',
      'ur': 'دانوب سپر مارکیٹ',
    },
    'tamimi': {
      'en': 'Tamimi Markets',
      'ar': 'أسواق التميمي',
      'ur': 'تمیمی مارکیٹس',
    },
    'carrefour': {
      'en': 'Carrefour',
      'ar': 'كارفور',
      'ur': 'کیریفور',
    },
    'lulu': {
      'en': 'Lulu Hypermarket',
      'ar': 'لولو هايبرماركت',
      'ur': 'لولو ہائپر مارکیٹ',
    },
    'jarir': {
      'en': 'Jarir Bookstore',
      'ar': 'مكتبة جرير',
      'ur': 'جریر بک اسٹور',
    },
    'extra': {
      'en': 'eXtra Stores',
      'ar': 'معارض إكسترا',
      'ur': 'ایکسٹرا اسٹورز',
    },
    'albaik': {
      'en': 'AlBaik',
      'ar': 'البيك',
      'ur': 'البيك',
    },
    'stc': {
      'en': 'stc Telecom',
      'ar': 'شركة الاتصالات السعودية (stc)',
      'ur': 'ایس ٹی سی ٹیلی کام',
    },
    'mobily': {
      'en': 'Mobily',
      'ar': 'موبايلي',
      'ur': 'موبائیلی',
    },
    'zain': {
      'en': 'Zain KSA',
      'ar': 'زين السعودية',
      'ur': 'زین کے ایس اے',
    },
    'saudi electricity': {
      'en': 'Saudi Electricity Company',
      'ar': 'الشركة السعودية للكهرباء',
      'ur': 'سعودی الیکٹرسٹی کمپنی',
    },
    'national water company': {
      'en': 'National Water Company',
      'ar': 'شركة المياه الوطنية',
      'ur': 'نیشنل واٹر کمپنی',
    },
  };

  String merchant(String? raw) {
    if (raw == null || raw.trim().isEmpty) {
      return get('unknown_merchant');
    }
    final clean = raw.trim();
    final lower = clean.toLowerCase();

    // 1. Exact match handling for generic placeholders
    if (lower == 'unknown' || lower == 'unknown merchant') {
      return get('unknown_merchant');
    }
    if (lower == 'direct' || lower == 'direct entry') {
      final lang = locale.languageCode;
      return _merchantDictionary['direct']?[lang] ?? _merchantDictionary['direct']?['en'] ?? clean;
    }
    if (lower == 'manual' || lower == 'manual expense') {
      final lang = locale.languageCode;
      return _merchantDictionary['manual']?[lang] ?? _merchantDictionary['manual']?['en'] ?? clean;
    }
    if (lower == 'installment purchase') {
      final lang = locale.languageCode;
      return _merchantDictionary['installment purchase']?[lang] ?? _merchantDictionary['installment purchase']?['en'] ?? clean;
    }

    // 2. Explicit exclusions to prevent false positive compound phrases
    // e.g., 'Panda Express' is a Chinese fast-food chain, not Panda Supermarket
    if (lower.contains('panda express')) {
      return clean;
    }

    // 3. Word-boundary regex matching across registered merchants
    for (final entry in _merchantDictionary.entries) {
      if (entry.key == 'unknown' ||
          entry.key == 'direct' ||
          entry.key == 'manual' ||
          entry.key == 'installment purchase') {
        continue;
      }

      // Word boundary matching ensures short tokens like 'stc' or 'extra' do not
      // greedily match inside words like 'Fastcare', 'Postcard', or 'Extraordinary'
      final pattern = RegExp(
        r'(?:^|[\s\b.,_\-/])' + RegExp.escape(entry.key) + r'(?:[\s\b.,_\-/]|$)',
        caseSensitive: false,
      );
      if (pattern.hasMatch(lower)) {
        final lang = locale.languageCode;
        return entry.value[lang] ?? entry.value['en'] ?? clean;
      }
    }
    return clean;
  }
}

extension LocalizationExtension on BuildContext {
  String tr(String key) => AppLocalizations.of(this).get(key);
  String trArgs(String key, Map<String, Object?> args) =>
      AppLocalizations.of(this).format(key, args);
  String trPlural(String key, num count, [Map<String, Object?> args = const {}]) =>
      AppLocalizations.of(this).plural(key, count, args);
  String sar(num amount, {int decimals = 2}) =>
      AppLocalizations.of(this).sar(amount, decimals: decimals);
  String money(num amount, String? currency, {int decimals = 2, bool signed = false}) =>
      AppLocalizations.of(this).money(amount, currency, decimals: decimals, signed: signed);
  String fmtDate(DateTime date, String pattern) =>
      AppLocalizations.of(this).date(date, pattern);
  String cycleMonth(String cycleKey, {String fallback = ''}) =>
      AppLocalizations.of(this).cycleMonth(cycleKey, fallback: fallback);
  String cycleLabel(String cycleKey, {String fallback = ''}) =>
      AppLocalizations.of(this).cycleLabel(cycleKey, fallback: fallback);
  String cycleRangeIso(String startIso, String endIso, {String fallback = ''}) =>
      AppLocalizations.of(this).cycleRangeIso(startIso, endIso, fallback: fallback);
  String trCat(String codeOrName) => AppLocalizations.of(this).category(codeOrName);
  String trSub(String subCodeOrName, {String? nameAr, String? nameEn}) =>
      AppLocalizations.of(this).subCategory(subCodeOrName, nameAr: nameAr, nameEn: nameEn);
  String trMerchant(String? raw) => AppLocalizations.of(this).merchant(raw);
  bool get isArabic => Localizations.localeOf(this).languageCode == 'ar';
  bool get isUrdu => Localizations.localeOf(this).languageCode == 'ur';
  bool get isRtl => isArabic || isUrdu;
}

class AppLocalizationsDelegate extends LocalizationsDelegate<AppLocalizations> {
  const AppLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) =>
      ['en', 'ar', 'ur'].contains(locale.languageCode);

  @override
  Future<AppLocalizations> load(Locale locale) async =>
      AppLocalizations(locale);

  @override
  bool shouldReload(AppLocalizationsDelegate old) => false;
}
